actions.script:
const support=ec.resource.script('component://mr-pass/screen/Support/Support.js'),p=ec.web.parameters
const token=support.param('token')
// a guest's order link admits a request about its one order (impl-shop P6, F27); its receipt stays on this page
const orderToken=support.orderLink(resolvedSiteId,support.param('orderId'))
const back={path:support.base(publicPath,'submit'),params:{token,orderId:support.param('orderId'),wikiPageId:support.param('wikiPageId'),
    requestCategoryId:support.param('requestCategoryId'),requestTypeEnumId:support.param('requestTypeEnumId')}}
// the template answers of the fields the page showed, by name (a checkbox or a multiple choice sends several)
const names=String(support.param('fieldNames') || '').split(',').map(s=>s.trim()).filter(s=>/^[A-Za-z][A-Za-z0-9_]{0,59}$/.test(s))
const values={}
for(const name of names){
    const value=p['tv_'+name]
    if(value==null || value==='')continue
    values[name]=Array.isArray(value)?value.map(String):(typeof value==='object' && value.length!=null?Array.from(value).map(String):String(value))
}
const input={siteId:resolvedSiteId,token,orderToken,requestName:support.param('requestName'),description:support.param('description'),
    requestCategoryId:support.param('requestCategoryId'),requestTypeEnumId:support.param('requestTypeEnumId'),
    customerPartyId:support.param('customerPartyId'),orderId:support.param('orderId'),wikiPageId:support.param('wikiPageId'),
    templateValues:JSON.stringify(values),firstName:support.param('firstName'),lastName:support.param('lastName'),
    emailAddress:support.param('emailAddress'),website:support.param('website'),file:support.file(),operationId:support.param('operationId')}
support.post('createCustomerCase',input,back,result=>result.requestId && !orderToken
    ? {path:passBases.support+'/CustomerCase',params:{requestId:result.requestId}}
    : {path:back.path,params:{token,received:'Y'}})

const support=ec.resource.script('component://mr-pass/screen/Support/Support.js'),p=ec.web.parameters
const orderId=support.param('orderId')
const orderToken=support.orderLink(resolvedSiteId,orderId)
const lines=Object.keys(p).filter(k=>/^cancel_[A-Za-z0-9]{1,20}$/.test(k)).map(k=>{const seq=k.slice(7)
    return {orderItemSeqId:seq,quantity:support.param('quantity_'+seq)}})
support.post('requestOrderCancel',{siteId:resolvedSiteId,orderToken,orderId,lines:JSON.stringify(lines),reason:support.param('reason'),
    consent:support.param('consent'),operationId:support.param('operationId')},{path:support.base(publicPath,'cancelOrder'),params:{orderId}})
